// eglGetNativeClientBufferANDROID: the engine's impeller ProcTable dlsyms this
// from libEGL.so to turn an AHardwareBuffer* into an EGLClientBuffer for
// eglCreateImageKHR(EGL_NATIVE_BUFFER_ANDROID). On acl the AHardwareBuffer* IS
// the client buffer our create-image M2 shim expects, so return it directly.
// Pure passthrough (no Mesa, no %fs bridge). Provenance:
// EGL_ANDROID_get_native_client_buffer. No GPL-3.0 sources.
__attribute__((visibility("default"))) void* eglGetNativeClientBufferANDROID(
    const void* buffer) {
  return (void*)buffer;
}

// eglPresentationTimeANDROID: EGL_ANDROID_presentation_time — set a surface's
// presentation time. Desktop Mesa/EGL has no such entrypoint, so this is a
// no-op returning EGL_TRUE; the symbol must exist (YouTube's libgoogle3.so
// references it) or its dlopen fails. Provenance: the EGL_ANDROID_
// presentation_time extension spec. No GPL-3.0 sources.
__attribute__((visibility("default"))) unsigned int
eglPresentationTimeANDROID(void* dpy, void* sur, long long time) {
  (void)dpy;
  (void)sur;
  (void)time;
  return 1u;  // EGL_TRUE
}

// eglDupNativeFenceFDANDROID: EGL_ANDROID_native_fence_sync — dup a sync's
// native fence fd. No such fence on desktop Mesa, so return
// EGL_NO_NATIVE_FENCE_FD_ANDROID (-1); callers CPU-sync.
__attribute__((visibility("default"))) int eglDupNativeFenceFDANDROID(
    void* dpy,
    void* sync) {
  (void)dpy;
  (void)sync;
  return -1;  // EGL_NO_NATIVE_FENCE_FD_ANDROID
}

